head.script:
scwin.vScrenID = "JLDFIL16300.xml";

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {

    scwin.fn_getHelpClssList();


};

// WebSquare 컴포넌트 이벤트 함수
/**
 * FAQ 탭 선택 시 Parameter, Content 초기화
 */
scwin.tac_faq_ontabclick = function (tabId, index) {
    let helpClssId = tac_faq.getTabID(index);
    let param = {
        "helpClssId" : helpClssId,
        "keyword" : ""
    };
    scwin.searchParamData = param;

	let wFrame = tac_faq.getFrame(index);
    let currentSrc = wFrame.getSrc();
    wFrame.setSrc(currentSrc);
};

// 일반 함수
/**
 * FAQ 카테고리 조회
 * @Desc : 로그인 전, 후 구분하여 조회
 */
scwin.fn_getHelpClssList = function () {
    scwin.isLogin = true; //임시
    if(scwin.isLogin) {
        $c.sbm.executeDynamic({ id: "sbm_SelectAfLoginHelpClssList", action: "/api/discls/support/faq-clss/select-list", method: "get", ref: "dma_helpClssReq", target: "dlt_HelpClssList=body", submitDoneHandler: scwin.sbm_SelectHelpClssList_submitdone, isProcessMsg: false });
    } else {
        $c.sbm.executeDynamic({ id: "sbm_SelectBfLoginHelpClssList", action: "/api/discls/guest/help/faq-clss/select-list", method: "get", ref: "dma_helpClssReq", target: "dlt_HelpClssList=body", submitDoneHandler: scwin.sbm_SelectHelpClssList_submitdone, isProcessMsg: false });
    }
};
/**
 * FAQ 카테고리 조회 콜백(성공)
 * @Desc : 탭 동적 생성
 *         (TabControl컴포넌트는 page형식이어서 _TAB.xml파일을 불러온 후 본문 조회 및 생성)
 */
scwin.sbm_SelectHelpClssList_submitdone = function (e) {
	const dataCount = dlt_HelpClssList.getRowCount();
    for (let i = 0; i < dataCount; i++) {
        const clssId = dlt_HelpClssList.getCellData(i, "helpClssId");
        const clssNm = dlt_HelpClssList.getCellData(i, "helpClssNm");

        let tabOpt = { 
            label : clssNm, 
            openAction : "exist",
            closable: false
        };

        let contOpt = {
            src:"/ui/support/JLDFIL16300_TAB1.xml",
            frameMode:"wframe", 
            wframe: true,
            scope:true,
            alwaysDraw:false
        };
        tac_faq.addTab(clssId, tabOpt, contOpt);
    }

    //'조회'버튼 페이지 TAB(hidden)
    let searchTabOpt = { 
        label : "조회", 
        openAction : "exist",
        closable: false,
        style: "display:none;"
    };

    let searchContOpt = {
        src:"/ui/support/JLDFIL16301.xml",
        frameMode:"wframe", 
        wframe: true,
        scope:true,
        alwaysDraw:false
    };
    tac_faq.addTab("tabs_search", searchTabOpt, searchContOpt);

};
